/** Reset GENERATED BY DEFAULT AS IDENTITY sequences for all tables **/

DROP FUNCTION IF EXISTS mapboard.reset_identity_sequence(text, text);
CREATE OR REPLACE FUNCTION mapboard.reset_identity_sequence(table_name text, column_name text) RETURNS bigint AS $$
  /** Reset the identity sequence for a given table **/
DECLARE
  seq_name text;
  schema_sep text;
  table_sep text;
  col text;
  is_identity boolean;
  res bigint;
BEGIN
  -- Get the qualified table name if specified
  IF position('.' IN table_name) > 0 THEN
    SELECT split_part(table_name, '.', 1), split_part(table_name, '.', 2) INTO schema_sep, table_sep;
  ELSE
    -- Find schema and table name in the search path
    SELECT n.nspname, c.relname INTO schema_sep, table_sep
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = table_name
    AND n.nspname = ANY (current_schemas(false))
    LIMIT 1;
    IF schema_sep IS NULL THEN
      RAISE EXCEPTION 'Table % does not exist in search path', table_name;
    END IF;
  END IF;

  SELECT pg_get_serial_sequence(table_name, column_name) INTO seq_name;

  -- Remove the current sequence or identity property
  -- check if is identit or default
  col := column_name;
  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns c
    WHERE c.table_schema = schema_sep
      AND c.table_name = table_sep
      AND c.column_name = col
      AND c.is_identity = 'YES'
  ) INTO is_identity;

  IF NOT is_identity THEN
    -- Add an identity sequence
    EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I DROP DEFAULT', schema_sep, table_sep, column_name);
    EXECUTE format('DROP SEQUENCE %I CASCADE', seq_name);
    EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I ADD GENERATED ALWAYS AS IDENTITY', schema_sep, table_sep, column_name);
    -- Get the new sequence name
    SELECT pg_get_serial_sequence(table_name, column_name) INTO seq_name;
  END IF;

  -- set the sequence to the max value in the column
  EXECUTE format(
    'SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM %I.%I), 0) + 1, false)',
    seq_name, column_name, schema_sep, table_sep
  );

  -- Get the next value of the sequence to ensure it's working
  EXECUTE format('SELECT nextval(%L)', seq_name) INTO res;

  RETURN res;
END;
$$
LANGUAGE plpgsql;


-- Reset identity sequences for all relevant tables
SELECT mapboard.reset_identity_sequence('mapboard.project', 'id');
SELECT mapboard.reset_identity_sequence('mapboard.canvas', 'id');
SELECT mapboard.reset_identity_sequence('mapboard.context', 'id');
